<?php
require_once dirname(__DIR__).'/app/bootstrap.php';
$city=trim((string)($_GET['city']??''));$cat=trim((string)($_GET['category']??''));$w=["l.status='published'"];$p=[];if($city!==''){$w[]='(l.city LIKE :c OR l.location LIKE :c)';$p[':c']='%'.$city.'%';}if($cat!==''){$w[]='l.category=:cat';$p[':cat']=$cat;}
$sql="SELECT l.*, (SELECT COUNT(*) FROM price_items pi WHERE pi.listing_id=l.id AND pi.is_active=1) price_count FROM listings l WHERE ".implode(' AND ',$w)." AND (EXISTS(SELECT 1 FROM availability_slots a WHERE a.listing_id=l.id AND a.is_active=1 AND a.slot_date>=date('now')) OR EXISTS(SELECT 1 FROM price_items pi WHERE pi.listing_id=l.id AND pi.is_active=1) OR EXISTS(SELECT 1 FROM owner_claims c WHERE c.listing_id=l.id AND c.status='approved')) ORDER BY l.featured DESC,l.name LIMIT 100";$s=db()->prepare($sql);$s->execute($p);$items=$s->fetchAll();
$pageTitle='Local marketplace | '.setting('site_name','MetroGuide');$pageDescription='Browse local businesses offering enquiries, bookings, services and price lists.';include __DIR__.'/includes/header.php';?>
<main id="main" class="container lg3-page"><div class="page-intro"><span class="eyebrow">LOCAL BUSINESS MARKETPLACE</span><h1>Make your next local connection.</h1><p>Explore participating businesses, review service lists, request appointments or ask for a quote. Requests are not confirmed until the business responds.</p></div>
<form class="lg3-filter-form" method="get"><label>City or neighbourhood<input name="city" value="<?= h($city) ?>" placeholder="Search an area"></label><label>Category<select name="category"><option value="">All categories</option><?php foreach(categories() as $c): ?><option value="<?= h($c) ?>" <?= $cat===$c?'selected':'' ?>><?= h($c) ?></option><?php endforeach; ?></select></label><button class="button button-primary">Filter businesses</button></form>
<?php if($items): ?><div class="listing-grid"><?php foreach($items as $listing)include __DIR__.'/includes/listing-card.php'; ?></div><?php else: ?><div class="empty-state"><h3>No marketplace listings yet</h3><p>Businesses with published service prices or booking availability will appear here. You can still use the main directory to contact businesses.</p><a class="button button-primary" href="<?= app_path('index.php') ?>">Explore directory</a></div><?php endif; ?></main><?php include __DIR__.'/includes/footer.php';?>
